import json, collections
import numpy as np
from sklearn.linear_model import Ridge
from exp2 import train, PERSONS
from exp8 import f2, K2

def clean_series(v):
    c=[r['core_temp'] for r in v]; n=len(c); ok=[c[i] is not None for i in range(n)]
    for i in range(1,n):
        if c[i] is not None and c[i-1] is not None and abs(c[i]-c[i-1])>0.2: ok[i]=False
    for i in range(1,n):
        if c[i] is not None and c[i-1] is not None and abs(c[i]-c[i-1])>0.2: ok[i-1]=False
    return ok
CLEAN2={k:clean_series(v) for k,v in train.items()}
for k in train:
    bad=[i+1 for i,x in enumerate(CLEAN2[k]) if not x]
    if bad: print('bad',k,bad)

def first_dec(h):
    w=[r['watts'] for r in h]; prev=None
    for i,x in enumerate(w):
        if x is None: continue
        if prev is not None and x<prev-0.5: return i+1
        prev=x
    return None

rows=[]
for pid in PERSONS:
    v=train[pid]; fd=first_dec(v)
    for n in range(4,46):
        if not CLEAN2[pid][n+14]: continue
        tgt=v[n+14]['core_temp']
        if tgt is None: continue
        if fd is not None and n<fd: continue
        rows.append((pid,n,f2(v[:n]),tgt))
print('rows',len(rows))
POP={}
for k in range(1,61):
    vals=[train[q][k-1]['core_temp'] for q in PERSONS if CLEAN2[q][k-1] and train[q][k-1]['core_temp'] is not None]
    POP[k]=float(np.median(vals))
print('pop', {k:round(POP[k],2) for k in (1,10,20,30,40,50,55,60)})

TIMEONLY=['lin','n2','sat','sqrt_n']
rows2=[(r[0],r[1],r[2],r[3]-POP[r[1]+15]) for r in rows]

def loo(rows, keys, alpha):
    pm={}; res=[]
    for pid in PERSONS:
        tr=[r for r in rows if r[0]!=pid]; te=[r for r in rows if r[0]==pid]
        if not te: continue
        X=np.array([[r[2][k] for k in keys] for r in tr]); Y=np.array([r[3] for r in tr])
        cnt=collections.Counter(r[0] for r in tr); W=np.array([1.0/cnt[r[0]] for r in tr])
        m=Ridge(alpha=alpha); m.fit(X,Y,sample_weight=W)
        Xt=np.array([[r[2][k] for k in keys] for r in te])
        p=m.predict(Xt); e=p-np.array([r[3] for r in te]); res.extend(e.tolist()); pm[pid]=float(np.mean(np.abs(e)))
    return float(np.mean(list(pm.values()))), pm, np.array(res)

for keys,name in ((K2,'all'),([k for k in K2 if k not in TIMEONLY],'no-time'),([k for k in K2 if k not in ('lin','n2','sqrt_n','sat','wkg_n','wkg8','hr_n','hr_sat','work_t')],'levelonly')):
    for a in (0.3,0.5,1.0,2.0,4.0,8.0):
        s,pm,res=loo(rows2,keys,a)
        print(name,a,round(s,4))
    print()
EOF
